// State registry. Source of truth is data/states.json (generated by
// scripts/generate-states.mjs from verified official sources — see STATES.md).
// hours is "all" (24/7), an object {days, openHour, closeHour}, or null
// (not published / not encodable — never guessed).
import { readFileSync } from "node:fs";

const payload = JSON.parse(readFileSync(new URL("../data/states.json", import.meta.url), "utf8"));
export const STATES = payload.states;

export function getState(code = "MN") {
  const want = String(code || "MN").toUpperCase();
  return STATES.find((s) => s.code === want) || null;
}

// Is the state system open at `date`, in the state's own timezone?
// Returns true/false, or null when availability is unknown.
export function isStateOpen(state, date = new Date()) {
  if (!state || state.hours === undefined) return null;
  if (state.hours === "all") return true;
  if (!state.hours) return null;
  const parts = new Intl.DateTimeFormat("en-US", {
    timeZone: state.timezone, weekday: "short", hour: "numeric", hourCycle: "h23",
  }).formatToParts(date);
  const map = Object.fromEntries(parts.map((p) => [p.type, p.value]));
  const day = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"].indexOf(map.weekday);
  const hour = Number(map.hour);
  return state.hours.days.includes(day) && hour >= state.hours.openHour && hour < state.hours.closeHour;
}

export function nextOpen(state, from = new Date()) {
  if (!state || state.hours === "all" || !state.hours) return null;
  const probe = new Date(from);
  for (let i = 0; i < 8 * 48; i++) {
    probe.setMinutes(probe.getMinutes() + 30);
    if (isStateOpen(state, probe)) return probe;
  }
  return null;
}

export function stateNow(state, date = new Date()) {
  return new Intl.DateTimeFormat("en-US", {
    timeZone: state.timezone, weekday: "long", month: "short", day: "numeric",
    hour: "numeric", minute: "2-digit", timeZoneName: "short",
  }).format(date);
}

// Back-compat name used by earlier MN-only code.
export const chicagoNow = (date = new Date()) => stateNow(getState("MN"), date);
